$ErrorActionPreference = "Stop"

$ProjectRoot = "D:\nctb-study-companion-starter"

if (-not (Test-Path (Join-Path $ProjectRoot "package.json"))) {
    throw "Project not found at $ProjectRoot"
}

Set-Location $ProjectRoot

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupRoot = Join-Path $ProjectRoot "backups\multibook-frontend-$timestamp"
[System.IO.Directory]::CreateDirectory($backupRoot) | Out-Null

$homeTarget = Join-Path $ProjectRoot "app\home\page.tsx"
$readerTarget = Join-Path $ProjectRoot "app\reader\page.tsx"

Copy-Item -LiteralPath $homeTarget -Destination (Join-Path $backupRoot "home-page.tsx") -Force
Copy-Item -LiteralPath $readerTarget -Destination (Join-Path $backupRoot "reader-page.tsx") -Force

$homeBase64 = @'

'@

$readerBase64 = @'

'@

[System.IO.File]::WriteAllBytes(
    $homeTarget,
    [System.Convert]::FromBase64String(($homeBase64 -replace "\s", ""))
)

[System.IO.File]::WriteAllBytes(
    $readerTarget,
    [System.Convert]::FromBase64String(($readerBase64 -replace "\s", ""))
)

Write-Host "" 
Write-Host "Multi-book frontend installed." -ForegroundColor Green
Write-Host "Backup: $backupRoot" -ForegroundColor Cyan
Write-Host "" 
Write-Host "Required OCR indexes:" -ForegroundColor Cyan

foreach ($bookId in @("class6-english", "class7-english", "class8-english")) {
    $indexPath = Join-Path $ProjectRoot "public\ocr\books\$bookId\index.json"
    if (Test-Path -LiteralPath $indexPath) {
        Write-Host "[FOUND] $bookId" -ForegroundColor Green
    } else {
        Write-Host "[MISSING] $bookId - run OCR before opening this book" -ForegroundColor Yellow
    }
}

Write-Host "" 
Write-Host "Now run:" -ForegroundColor Cyan
Write-Host "  Remove-Item .next -Recurse -Force -ErrorAction SilentlyContinue"
Write-Host "  npm run dev"
